import json, re, shutil, hashlib
from pathlib import Path
from datetime import datetime

home = Path('/Users/chongya')
src_root = home/'.openclaw'
repo = home/'.openclaw/workspace/openclaw_data'
ts = datetime.now().strftime('%Y%m%d-%H%M%S')
out = repo/'backups'/'openclaw-config'/ts
out.mkdir(parents=True, exist_ok=True)

files = [
    '.openclaw/openclaw.json',
    '.openclaw/openclaw.json.bak',
    '.openclaw/cron/jobs.json',
    '.openclaw/exec-approvals.json',
    '.openclaw/update-check.json',
    '.openclaw/identity/device.json',
    '.openclaw/identity/device-auth.json',
    '.openclaw/devices/paired.json',
    '.openclaw/devices/pending.json',
    '.openclaw/credentials/oauth.json',
]
# include agent auth/config-like json files
agents_dir = src_root/'agents'
if agents_dir.exists():
    for p in agents_dir.rglob('*.json'):
        rel = p.relative_to(home).as_posix()
        files.append(rel)

seen = set(); ordered=[]
for f in files:
    if f not in seen:
        seen.add(f); ordered.append(f)

SENSITIVE_KEY = re.compile(r'(token|secret|password|passwd|apikey|api_key|key|authorization|cookie|session|oauth|client_secret|private|access[_-]?token|refresh[_-]?token)', re.I)

def mask_value(v):
    if v is None:
        return None
    s = str(v)
    if len(s) <= 8:
        return '***REDACTED***'
    return s[:3] + '***REDACTED***' + s[-3:]

def redact(obj, parent_key=''):
    if isinstance(obj, dict):
        outd = {}
        for k, v in obj.items():
            if SENSITIVE_KEY.search(k):
                outd[k] = mask_value(v)
            else:
                outd[k] = redact(v, k)
        return outd
    if isinstance(obj, list):
        return [redact(x, parent_key) for x in obj]
    if isinstance(obj, str):
        # generic bearer/jwt-like masking
        if parent_key and SENSITIVE_KEY.search(parent_key):
            return mask_value(obj)
        if obj.startswith('gho_') or obj.startswith('ghp_') or obj.startswith('github_pat_'):
            return mask_value(obj)
        if len(obj) > 40 and re.search(r'[A-Za-z0-9_\-]{20,}', obj):
            # conservative: long high-entropy-ish strings
            return mask_value(obj)
        return obj
    return obj

manifest = {
    'created_at': datetime.now().isoformat(),
    'source_root': str(src_root),
    'backup_type': 'sanitized-config-snapshot',
    'files': []
}

for rel in ordered:
    src = home/rel
    if not src.exists() or not src.is_file():
        continue
    dst = out/rel.replace('.openclaw/','')
    dst.parent.mkdir(parents=True, exist_ok=True)
    record = {'source': str(src), 'backup': str(dst), 'status':'ok'}
    try:
        raw = src.read_text(encoding='utf-8')
        try:
            data = json.loads(raw)
            red = redact(data)
            txt = json.dumps(red, ensure_ascii=False, indent=2)
            dst.write_text(txt + '\n', encoding='utf-8')
            record['mode'] = 'json-redacted'
        except Exception:
            # fallback plain copy
            dst.write_text(raw, encoding='utf-8')
            record['mode'] = 'plain-copy'
        record['sha256'] = hashlib.sha256(dst.read_bytes()).hexdigest()
    except Exception as e:
        record['status']='error'; record['error']=str(e)
    manifest['files'].append(record)

(manifest_path := out/'MANIFEST.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
print(out)
print('files:', len(manifest['files']))
print('manifest:', manifest_path)
